/* ========================================================================
   QARTEXA V4: STAFF PORTAL EXTENSIONS  (js/qx-admin2.js)
   Appearance studio, Social media, Form builder, Form submissions,
   Staff & roles, Activity log (with restore).
   Registered into the portal by js/qx-admin.js through window.QXA_EXT.
   ======================================================================== */
window.QXA_EXT=function(A){
'use strict';
var QX=A.QX,E=A.E,$=A.$,main=A.main,field=A.field,toast=A.toast,openModal=A.openModal,closeModal=A.closeModal,S=A.S,badge=A.badge;
var TH=window.QX_THEME,ICONS=window.QX_ICONS||{};
var ROLES=[['super_admin','Super Administrator','Everything, including staff accounts'],['admin','Administrator','Content, jobs, tenders, forms, submissions, appearance, activity log'],['editor','Website Editor','Pages, content, appearance, social links and form design'],['hr','HR Manager','Jobs and applications only'],['content','Content Manager','Solutions, blog, partners and tenders']];
var dt=function(d){return d?new Date(d).toLocaleString('en-GB',{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}):'';};
var msg=function(el,t,bad){el.innerHTML='<div class="qx-status '+(bad?'err':'ok')+'">'+E(t)+'</div>';};
var csvCell=function(v){return '"'+String(v==null?'':(typeof v==='object'?JSON.stringify(v):v)).replace(/"/g,'""')+'"';};
function download(name,rows){var b=new Blob(['\ufeff'+rows.map(function(r){return r.map(csvCell).join(',');}).join('\r\n')],{type:'text/csv'});var a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=name;a.click();setTimeout(function(){URL.revokeObjectURL(a.href);},2000);}
function confirmBox(text,okLabel,fn){openModal('<h2 style="margin-top:0">Please confirm</h2><p>'+E(text)+'</p><div class="qa-actions"><button class="qx-btn" id="cf-ok" style="background:#b00000">'+E(okLabel||'Confirm')+'</button><button class="qx-btn ghost" id="cf-no">Cancel</button></div>');$('#cf-no').onclick=closeModal;$('#cf-ok').onclick=function(){closeModal();fn();};}
function css(){if(document.getElementById('qa2-css'))return;var s=document.createElement('style');s.id='qa2-css';s.textContent=
'.qa2-tabs{display:flex;gap:4px;flex-wrap:wrap;margin:0 0 14px;border-bottom:1px solid #dbe8f2}.qa2-tabs button{background:none;border:0;padding:10px 14px;font:inherit;font-weight:700;color:#4f6377;cursor:pointer;border-bottom:3px solid transparent}.qa2-tabs button[aria-selected=true]{color:#062650;border-color:#e80000}'+
'.qa2-studio{display:grid;grid-template-columns:minmax(300px,380px) 1fr;gap:20px;align-items:start}@media(max-width:1000px){.qa2-studio{grid-template-columns:1fr}}'+
'.qa2-ctl{background:#fff;border:1px solid #dbe8f2;border-radius:10px;padding:16px;max-height:78vh;overflow:auto}.qa2-row{display:grid;grid-template-columns:1fr auto;gap:8px;align-items:center;margin:0 0 12px}.qa2-row label{font-size:13px;font-weight:600;color:#172b43}.qa2-row input[type=color]{width:44px;height:34px;padding:0;border:1px solid #cdd9e5;border-radius:6px;background:#fff}'+
'.qa2-hex{display:flex;gap:6px;align-items:center}.qa2-hex input[type=text]{width:92px;font-family:monospace}.qa2-range{grid-column:1/3;display:flex;gap:10px;align-items:center}.qa2-range input{flex:1}.qa2-range output{min-width:54px;text-align:right;font-size:13px;color:#4f6377}'+
'.qa2-sel{grid-column:1/3}.qa2-sel select,.qa2-sel input{width:100%}.qa2-prev{background:#e9eff5;border:1px solid #dbe8f2;border-radius:10px;padding:10px;position:sticky;top:12px}.qa2-prev-bar{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px;align-items:center}.qa2-frame{display:block;margin:0 auto;border:0;background:#fff;border-radius:6px;box-shadow:0 4px 18px rgba(6,38,80,.15);height:72vh;max-width:100%;transition:width .2s}'+
'.qa2-warn{background:#fff7e6;border:1px solid #f0d28a;color:#6b4a00;border-radius:8px;padding:8px 10px;font-size:13px;margin:6px 0}.qa2-list{width:100%;border-collapse:collapse;background:#fff;border:1px solid #dbe8f2;border-radius:10px;overflow:hidden}.qa2-list th,.qa2-list td{padding:10px 12px;text-align:left;border-bottom:1px solid #eaf1f7;font-size:14px;vertical-align:middle}.qa2-list th{background:#f7fbfe;font-size:12px;text-transform:uppercase;letter-spacing:.5px;color:#4f6377}'+
'.qa2-ic{width:34px;height:34px;display:inline-grid;place-items:center;background:#062650;color:#fff;border-radius:50%}.qa2-ic svg{width:17px;height:17px;fill:currentColor}.qa2-iconpick{display:grid;grid-template-columns:repeat(auto-fill,minmax(54px,1fr));gap:6px;max-height:190px;overflow:auto;border:1px solid #dbe8f2;border-radius:8px;padding:8px}.qa2-iconpick label{display:grid;place-items:center;gap:2px;font-size:10px;cursor:pointer;padding:6px 2px;border-radius:6px;border:2px solid transparent;text-align:center}.qa2-iconpick input{position:absolute;opacity:0}.qa2-iconpick input:checked+span{outline:2px solid #e80000;outline-offset:3px}.qa2-mini{padding:4px 9px;font-size:12px}.qa2-grid2{display:grid;grid-template-columns:1fr 1fr;gap:12px}@media(max-width:700px){.qa2-grid2{grid-template-columns:1fr}}.qa2-pre{background:#f7fbfe;border:1px solid #dbe8f2;border-radius:8px;padding:10px;font-size:12px;max-height:220px;overflow:auto;white-space:pre-wrap;word-break:break-word}';
document.head.appendChild(s);}
function svgIcon(row){var m=row.icon_svg?QX.safe.svg(row.icon_svg):null;if(m)return m;var ic=ICONS[row.icon_key]||ICONS[row.platform]||ICONS.link;return ic?'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="'+ic[1].replace(/"/g,'')+'"/></svg>':'';}

/* =========================== APPEARANCE STUDIO =========================== */
function appearance(){
  css();
  main.innerHTML='<h1>Appearance</h1><div class="qa-loading">Loading…</div>';
  Promise.all([S.list('site_settings',{where:{key:'theme'}}),S.list('site_settings',{where:{key:'theme_draft'}})]).then(function(r){
    var pub=TH.clean(r[0][0]&&r[0][0].value),hasDraft=!!(r[1][0]&&r[1][0].value),cur=TH.clean(hasDraft?r[1][0].value:pub);
    var hist=[TH.clone(cur)],hi=0,tab='colors',device='100%',page='index.html',timer=null,dirty=false;
    var get=function(p){return p.split('.').reduce(function(o,k){return o[k];},cur);};
    var set=function(p,v){var a=p.split('.'),o=cur;while(a.length>1)o=o[a.shift()];o[a[0]]=v;cur=TH.clean(cur);dirty=true;queue();preview();};
    function queue(){clearTimeout(timer);timer=setTimeout(function(){hist=hist.slice(0,hi+1);hist.push(TH.clone(cur));if(hist.length>60)hist.shift();hi=hist.length-1;btns();},450);}
    function flush(){clearTimeout(timer);timer=null;if(JSON.stringify(hist[hi])!==JSON.stringify(cur)){hist=hist.slice(0,hi+1);hist.push(TH.clone(cur));if(hist.length>60)hist.shift();hi=hist.length-1;}}
    function preview(){var f=$('#ap-frame');if(f&&f.contentWindow)f.contentWindow.postMessage({type:'qx-theme-preview',theme:cur},location.origin);warn();}
    function lum(h){var c=[1,3,5].map(function(i){var v=parseInt(h.substr(i,2),16)/255;return v<=0.03928?v/12.92:Math.pow((v+0.055)/1.055,2.4);});return .2126*c[0]+.7152*c[1]+.0722*c[2];}
    function ratio(a,b){var x=lum(a),y=lum(b);return (Math.max(x,y)+.05)/(Math.min(x,y)+.05);}
    function warn(){var C=cur.colors,w=[];[['Body text on background',C.text,C.bg],['Button text on button',C.btnText,C.btnBg],['Header text on header',C.headerText,C.headerBg],['Footer text on footer',C.footerText,C.footerBg],['Top-bar text on top bar',C.topbarText,C.topbarBg]].forEach(function(p){var q=ratio(p[1],p[2]);if(q<4.5)w.push(p[0]+': contrast '+q.toFixed(1)+':1 (aim for 4.5:1 or higher)');});var el=$('#ap-warn');if(el)el.innerHTML=w.map(function(x){return '<div class="qa2-warn">⚠ '+E(x)+'</div>';}).join('');}
    function colorRow(p,l){var v=get(p);return '<div class="qa2-row"><label for="c-'+p+'">'+E(l)+'</label><div class="qa2-hex"><input type="text" data-hex="'+p+'" value="'+v+'" maxlength="7" aria-label="'+E(l)+' hex code"><input type="color" id="c-'+p+'" data-col="'+p+'" value="'+v+'"></div></div>';}
    function optColor(p,l){var v=get(p);return '<div class="qa2-row"><label for="c-'+p+'">'+E(l)+'</label><div class="qa2-hex"><input type="text" data-hex="'+p+'" data-opt="1" value="'+v+'" placeholder="default" maxlength="7"><input type="color" data-col="'+p+'" data-opt="1" value="'+(v||'#ffffff')+'"></div></div>';}
    function range(p,l,min,max,step,unit,blankable){var v=get(p);return '<div class="qa2-row"><label>'+E(l)+'</label><div class="qa2-range"><input type="range" data-rng="'+p+'" min="'+min+'" max="'+max+'" step="'+step+'" value="'+(v===''?min:v)+'" aria-label="'+E(l)+'"><output>'+(v===''?'default':v+unit)+'</output>'+(blankable?'<button type="button" class="qx-btn ghost qa2-mini" data-clr="'+p+'">Reset</button>':'')+'</div></div>';}
    function sel(p,l,opts){var v=get(p);return '<div class="qa2-row"><label>'+E(l)+'</label><div class="qa2-sel"><select data-sel="'+p+'" aria-label="'+E(l)+'">'+opts.map(function(o){return '<option value="'+E(o[0])+'"'+(String(v)===String(o[0])?' selected':'')+'>'+E(o[1])+'</option>';}).join('')+'</select></div></div>';}
    function fontOpts(){var o=Object.keys(TH.FONTS).map(function(k){return [k,TH.FONTS[k].label];});[cur.type.bodyFont,cur.type.headFont].forEach(function(k){if(!TH.FONTS[k]&&TH.fontInfo(k)&&!o.some(function(x){return x[0]===k;}))o.push([k,TH.fontInfo(k).label]);});return o;}
    var TABS=[['colors','Colours'],['type','Typography'],['shape','Layout & shapes'],['sections','Section colours'],['motion','Animation'],['devices','Tablet & mobile']];
    function panel(){
      var h='';
      if(tab==='colors'){h+='<h3 style="margin-top:0">Brand colours</h3>'+colorRow('colors.primary','Primary (navy)')+colorRow('colors.primary2','Secondary navy')+colorRow('colors.accent','Accent (red)')+colorRow('colors.sky','Sky blue')+'<h3>Page</h3>'+colorRow('colors.bg','Page background')+colorRow('colors.bgAlt','Soft background')+colorRow('colors.text','Body text')+colorRow('colors.muted','Muted text')+colorRow('colors.heading','Headings')+colorRow('colors.border','Borders')+'<h3>Links & buttons</h3>'+colorRow('colors.link','Link')+colorRow('colors.linkHover','Link hover')+colorRow('colors.btnBg','Button')+colorRow('colors.btnText','Button text')+colorRow('colors.btnHover','Button hover')+'<h3>Header & footer</h3>'+colorRow('colors.topbarBg','Top bar')+colorRow('colors.topbarText','Top-bar text')+colorRow('colors.headerBg','Header')+colorRow('colors.headerText','Header menu text')+colorRow('colors.footerBg','Footer')+colorRow('colors.footerText','Footer text');}
      if(tab==='type'){h+='<h3 style="margin-top:0">Fonts</h3>'+sel('type.bodyFont','Body font',fontOpts())+sel('type.headFont','Heading font',fontOpts())+'<div class="qa2-row"><label>Add another Google font</label><div class="qa2-sel"><input type="text" id="ap-gf" placeholder="e.g. Roboto Slab" maxlength="40"><button type="button" class="qx-btn ghost qa2-mini" id="ap-gfb" style="margin-top:6px">Use as body font</button> <button type="button" class="qx-btn ghost qa2-mini" id="ap-gfh" style="margin-top:6px">Use as heading font</button><small class="qa-muted" style="display:block;margin-top:4px">Type the exact name from fonts.google.com. Google Fonts are open-licence. Visitors’ browsers load them from Google.</small></div></div><h3>Sizes & spacing</h3>'+range('type.baseSize','Body text size',13,22,1,'px')+range('type.lineHeight','Line spacing',1.2,2.2,0.05,'')+range('type.letterSpacing','Body letter spacing',-0.05,0.2,0.01,'em')+range('type.paragraphSpacing','Paragraph spacing',0.4,2.5,0.1,'em')+'<h3>Headings</h3>'+sel('type.headWeight','Heading weight',[[400,'Regular'],[500,'Medium'],[600,'Semi-bold'],[700,'Bold'],[800,'Extra-bold (default)'],[900,'Black']])+sel('type.bodyWeight','Body weight',[[300,'Light'],[400,'Regular (default)'],[500,'Medium'],[600,'Semi-bold']])+range('type.headLetter','Heading letter spacing',-0.08,0.15,0.005,'em',true)+sel('type.headTransform','Heading case',[['none','Normal'],['uppercase','UPPERCASE'],['capitalize','Capitalize Words']]);}
      if(tab==='shape'){h+='<h3 style="margin-top:0">Shapes</h3>'+range('shape.cardRadius','Card corner radius',0,40,1,'px')+range('shape.btnRadius','Button corner radius',0,40,1,'px')+range('shape.imageRadius','Image corner radius',0,40,1,'px')+sel('shape.cardStyle','Card style',[['default','Default'],['flat','Flat (soft background)'],['bordered','Outlined'],['raised','Raised']])+sel('shape.shadow','Shadow strength',[['default','Default'],['none','None'],['soft','Soft'],['medium','Medium'],['strong','Strong']])+'<h3>Layout</h3>'+range('shape.maxWidth','Content width',1000,1600,20,'px')+sel('shape.sectionSpacing','Section spacing',[['compact','Compact'],['normal','Normal (default)'],['spacious','Spacious']]);}
      if(tab==='sections'){h+='<p class="qa-muted" style="margin-top:0">Give a type of section its own colours. Leave empty to keep the normal look.</p>';Object.keys(TH.SECTION_LABELS).forEach(function(k){h+='<h3>'+E(TH.SECTION_LABELS[k])+'</h3>'+optColor('sections.'+k+'.bg','Background')+optColor('sections.'+k+'.text','Text');});}
      if(tab==='motion'){h+='<h3 style="margin-top:0">Animation</h3>'+sel('motion.enabled','Animations',[['true','On'],['false','Off']])+range('motion.speed','Speed',0.5,2,0.1,'×')+sel('motion.intensity','Hover intensity',[['subtle','Subtle'],['normal','Normal'],['lively','Lively']])+'<p class="qa-muted">Visitors who have “reduce motion” turned on in their device always get reduced motion, whatever you choose here.</p>';}
      if(tab==='devices'){h+='<p class="qa-muted" style="margin-top:0">Optional overrides. Leave on “default” to inherit the desktop settings.</p><h3>Tablet (641–1024 px)</h3>'+range('tablet.baseSize','Body text size',12,22,1,'px',true)+range('tablet.maxWidth','Content width',600,1200,20,'px',true)+'<h3>Mobile (up to 640 px)</h3>'+range('mobile.baseSize','Body text size',12,22,1,'px',true)+sel('mobile.sectionSpacing','Section spacing',[['','Default'],['compact','Compact'],['normal','Normal'],['spacious','Spacious']]);}
      return h;
    }
    function btns(){var u=$('#ap-undo'),r=$('#ap-redo');if(u)u.disabled=hi<1;if(r)r.disabled=hi>=hist.length-1;}
    function draw(){
      main.innerHTML='<div class="qa-head"><h1>Appearance</h1><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="qx-btn ghost" id="ap-undo">↶ Undo</button><button class="qx-btn ghost" id="ap-redo">↷ Redo</button><button class="qx-btn ghost" id="ap-cancel">Cancel changes</button><button class="qx-btn ghost" id="ap-reset">Restore Qartexa default</button><button class="qx-btn ghost" id="ap-draft">Save draft</button><button class="qx-btn" id="ap-pub">Publish</button></div></div>'+
      '<p class="qa-muted" style="max-width:820px;margin:-6px 0 14px">Change anything on the left and watch the preview. Nothing is public until you press <strong>Publish</strong>. “Save draft” keeps your work for later. '+(hasDraft?'<strong>A saved draft was loaded.</strong>':'')+'</p><div id="ap-msg" role="status"></div><div class="qa2-studio"><div><div class="qa2-tabs" role="tablist">'+TABS.map(function(t){return '<button type="button" role="tab" data-tab="'+t[0]+'" aria-selected="'+(t[0]===tab)+'">'+E(t[1])+'</button>';}).join('')+'</div><div class="qa2-ctl" id="ap-ctl">'+panel()+'</div><div id="ap-warn"></div></div>'+
      '<div class="qa2-prev"><div class="qa2-prev-bar"><button class="qx-btn ghost qa2-mini" data-dev="100%">Desktop</button><button class="qx-btn ghost qa2-mini" data-dev="820px">Tablet</button><button class="qx-btn ghost qa2-mini" data-dev="390px">Mobile</button><select id="ap-page" aria-label="Preview page"><option value="index.html">Home</option><option value="about.html">About</option><option value="solutions.html">Solutions</option><option value="careers.html">Careers</option><option value="contact.html">Contact</option><option value="blog.html">Blog</option></select><span class="qa-muted" style="font-size:12px">Live preview</span></div><iframe class="qa2-frame" id="ap-frame" title="Website preview" style="width:'+device+'" src="'+page+'?qx_preview=1"></iframe></div></div>';
      var ctl=$('#ap-ctl');
      $('#ap-frame').addEventListener('load',preview);
      main.querySelectorAll('[data-tab]').forEach(function(b){b.onclick=function(){tab=b.dataset.tab;ctl.innerHTML=panel();main.querySelectorAll('[data-tab]').forEach(function(x){x.setAttribute('aria-selected',x===b);});bind();};});
      main.querySelectorAll('[data-dev]').forEach(function(b){b.onclick=function(){device=b.dataset.dev;$('#ap-frame').style.width=device;};});
      $('#ap-page').onchange=function(){page=this.value;$('#ap-frame').src=page+'?qx_preview=1';};
      $('#ap-undo').onclick=function(){flush();if(hi>0){hi--;cur=TH.clean(hist[hi]);dirty=true;ctl.innerHTML=panel();bind();preview();btns();}};
      $('#ap-redo').onclick=function(){flush();if(hi<hist.length-1){hi++;cur=TH.clean(hist[hi]);dirty=true;ctl.innerHTML=panel();bind();preview();btns();}};
      $('#ap-cancel').onclick=function(){cur=TH.clean(hasDraft?r[1][0].value:pub);hist=[TH.clone(cur)];hi=0;dirty=false;ctl.innerHTML=panel();bind();preview();btns();msg($('#ap-msg'),'Changes cancelled.');};
      $('#ap-reset').onclick=function(){confirmBox('Reset every colour, font and shape to the original Qartexa theme? This only changes the editor. Nothing is public until you press Publish.','Reset',function(){cur=TH.clean({});dirty=true;queue();ctl.innerHTML=panel();bind();preview();msg($('#ap-msg'),'Qartexa default loaded. Press Publish to make it live.');});};
      $('#ap-draft').onclick=async function(){try{await A.putSetting('theme_draft',cur);hasDraft=true;r[1]=[{value:TH.clone(cur)}];dirty=false;msg($('#ap-msg'),'Draft saved. Visitors still see the published design.');}catch(e){msg($('#ap-msg'),e.message,1);}};
      $('#ap-pub').onclick=function(){confirmBox('Publish this design to the whole website now?','Publish',async function(){try{await A.putSetting('theme',cur);await A.putSetting('theme_draft',cur);pub=TH.clean(cur);hasDraft=true;r[1]=[{value:TH.clone(cur)}];dirty=false;try{localStorage.removeItem(TH.key);sessionStorage.clear();}catch(e){}msg($('#ap-msg'),'Published. Visitors see the new design within a couple of minutes (their browser keeps a short-lived copy).');}catch(e){msg($('#ap-msg'),e.message,1);}});};
      bind();btns();warn();
    }
    function bind(){
      var ctl=$('#ap-ctl');if(!ctl)return;
      ctl.querySelectorAll('[data-col]').forEach(function(i){i.oninput=function(){var p=i.dataset.col;set(p,i.value);var h=ctl.querySelector('[data-hex="'+p+'"]');if(h)h.value=i.value;};});
      ctl.querySelectorAll('[data-hex]').forEach(function(i){i.onchange=function(){var p=i.dataset.hex,v=i.value.trim();if(!v&&i.dataset.opt){set(p,'');return;}if(/^#?[0-9a-f]{6}$/i.test(v)||/^#?[0-9a-f]{3}$/i.test(v)){if(v[0]!=='#')v='#'+v;set(p,v);i.value=get(p);var c=ctl.querySelector('[data-col="'+p+'"]');if(c)c.value=get(p);}else{i.value=get(p);toast('Enter a colour like #062650',true);}};});
      ctl.querySelectorAll('[data-rng]').forEach(function(i){i.oninput=function(){set(i.dataset.rng,Number(i.value));var o=i.parentNode.querySelector('output');o.textContent=get(i.dataset.rng)+(i.dataset.rng.indexOf('Spacing')>-1&&i.dataset.rng.indexOf('letter')<0?'':'');o.textContent=get(i.dataset.rng)+(/baseSize|Radius|maxWidth/.test(i.dataset.rng)?'px':(/speed/.test(i.dataset.rng)?'×':(/letter|Letter|paragraph/.test(i.dataset.rng)?'em':'')));};});
      ctl.querySelectorAll('[data-clr]').forEach(function(b){b.onclick=function(){set(b.dataset.clr,'');ctl.innerHTML=panel();bind();};});
      ctl.querySelectorAll('[data-sel]').forEach(function(i){i.onchange=function(){var v=i.value;if(i.dataset.sel==='motion.enabled')v=v==='true';set(i.dataset.sel,v);ctl.innerHTML=panel();bind();};});
      var g=function(which){return function(){var n=($('#ap-gf').value||'').trim();if(!/^[A-Za-z][A-Za-z0-9 ]{1,39}$/.test(n)){toast('Use only letters, numbers and spaces.',true);return;}set(which,'g:'+n);ctl.innerHTML=panel();bind();};};
      if($('#ap-gfb')){$('#ap-gfb').onclick=g('type.bodyFont');$('#ap-gfh').onclick=g('type.headFont');}
    }
    draw();
    window.addEventListener('beforeunload',function(e){if(dirty&&location.hash==='#appearance'){e.preventDefault();e.returnValue='';}});
  }).catch(function(e){main.innerHTML='<h1>Appearance</h1><div class="qx-status err">'+E(e.message)+'</div>';});
}

/* =============================== SOCIAL MEDIA ============================== */
function social(){
  css();
  main.innerHTML='<h1>Social media</h1><div class="qa-loading">Loading…</div>';
  S.list('social_links',{order:['sort_order','asc']}).then(function(rows){
    var where={header:'Header',footer:'Footer',contact:'Contact page'};
    main.innerHTML='<div class="qa-head"><h1>Social media</h1><button class="qx-btn" id="so-add">+ Add account</button></div><p class="qa-muted" style="max-width:760px;margin:-6px 0 16px">Add as many accounts as you like. They appear where you tick: the header, the footer and the Contact page. Changes go live straight away.</p><div id="so-msg" role="status"></div>'+
    (rows.length?'<table class="qa2-list"><thead><tr><th>Icon</th><th>Name</th><th>Link</th><th>Shown in</th><th>Status</th><th></th></tr></thead><tbody>'+rows.map(function(r,i){return '<tr><td><span class="qa2-ic">'+svgIcon(r)+'</span></td><td><strong>'+E(r.name)+'</strong></td><td style="max-width:260px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+E(r.url)+'</td><td>'+E((r.placements||[]).map(function(p){return where[p];}).join(', ')||'—')+'</td><td>'+badge(r.visible?'published':'draft',[['published','Visible'],['draft','Hidden']])+'</td><td style="white-space:nowrap"><button class="qx-btn ghost qa2-mini" data-up="'+i+'" '+(i?'':'disabled')+' aria-label="Move up">↑</button> <button class="qx-btn ghost qa2-mini" data-dn="'+i+'" '+(i<rows.length-1?'':'disabled')+' aria-label="Move down">↓</button> <button class="qx-btn ghost qa2-mini" data-vis="'+i+'">'+(r.visible?'Hide':'Show')+'</button> <button class="qx-btn ghost qa2-mini" data-ed="'+i+'">Edit</button> <button class="qx-btn ghost qa2-mini" data-del="'+i+'">Delete</button></td></tr>';}).join('')+'</tbody></table>':'<div class="qa-empty">No accounts yet. The website footer shows its original icons until you add one here.</div>');
    $('#so-add').onclick=function(){edit(null);};
    var by=function(a,fn){main.querySelectorAll('['+a+']').forEach(function(b){b.onclick=function(){fn(+b.getAttribute(a));};});};
    by('data-ed',function(i){edit(rows[i]);});
    by('data-vis',async function(i){try{await S.save('social_links',{id:rows[i].id,visible:!rows[i].visible});social();}catch(e){toast(e.message,true);}});
    by('data-up',function(i){swap(i,i-1);});by('data-dn',function(i){swap(i,i+1);});
    by('data-del',function(i){confirmBox('Delete “'+rows[i].name+'”? It disappears from the website.','Delete',async function(){try{await S.remove('social_links',rows[i].id);social();}catch(e){toast(e.message,true);}});});
    async function swap(a,b){try{var A1=rows[a],B1=rows[b],sa=A1.sort_order,sb=B1.sort_order;if(sa===sb){sa=a*10;sb=b*10;}await S.save('social_links',{id:A1.id,sort_order:sb});await S.save('social_links',{id:B1.id,sort_order:sa});social();}catch(e){toast(e.message,true);}}
    function edit(r){
      var isNew=!r;r=r||{platform:'linkedin',name:'',url:'https://',icon_key:'linkedin',icon_svg:null,placements:['footer'],visible:true,sort_order:(rows.length+1)*10};
      var custom=!!r.icon_svg,svg=r.icon_svg||'',plats=Object.keys(ICONS);
      openModal('<h2 style="margin-top:0">'+(isNew?'Add':'Edit')+' social account</h2><form id="so-f" novalidate>'+
        field('Platform','<select id="so-p">'+plats.map(function(k){return '<option value="'+k+'"'+(r.platform===k?' selected':'')+'>'+E(ICONS[k][0])+'</option>';}).join('')+'<option value="custom"'+(r.platform==='custom'?' selected':'')+'>Other / custom platform</option></select>')+
        field('Name shown to visitors','<input type="text" id="so-n" maxlength="60" value="'+E(r.name)+'">','Used as the tooltip and for screen readers.',1)+
        field('Profile link','<input type="url" id="so-u" value="'+E(r.url)+'" placeholder="https://…">','Must start with https:// (or mailto: / tel: for email and phone).',1)+
        '<div class="qx-field"><label>Icon</label><div class="qa2-iconpick" id="so-ic">'+plats.map(function(k){return '<label title="'+E(ICONS[k][0])+'"><input type="radio" name="ic" value="'+k+'"'+(!custom&&r.icon_key===k?' checked':'')+'><span class="qa2-ic"><svg viewBox="0 0 24 24"><path d="'+ICONS[k][1].replace(/"/g,'')+'"/></svg></span></label>';}).join('')+'<label title="Custom SVG"><input type="radio" name="ic" value="__custom"'+(custom?' checked':'')+'><span class="qa2-ic" style="background:#e80000;font-size:11px;font-weight:800">SVG</span></label></div></div>'+
        '<div id="so-cu" '+(custom?'':'hidden')+'>'+field('Custom icon (SVG code)','<textarea id="so-svg" rows="4" placeholder="&lt;svg viewBox=&quot;0 0 24 24&quot;&gt;…&lt;/svg&gt;">'+E(svg)+'</textarea><input type="file" id="so-file" accept=".svg,image/svg+xml">','Only simple shapes are kept. Scripts, styles and links inside the file are removed automatically.')+'</div>'+
        field('Show in','<label style="display:block"><input type="checkbox" class="so-pl" value="header"'+(r.placements.indexOf('header')>-1?' checked':'')+'> Header (large screens)</label><label style="display:block"><input type="checkbox" class="so-pl" value="footer"'+(r.placements.indexOf('footer')>-1?' checked':'')+'> Footer</label><label style="display:block"><input type="checkbox" class="so-pl" value="contact"'+(r.placements.indexOf('contact')>-1?' checked':'')+'> Contact page</label>')+
        '<label style="display:block;margin:6px 0"><input type="checkbox" id="so-v"'+(r.visible?' checked':'')+'> Visible on the website</label>'+
        '<div class="qx-field"><label>Preview</label><div id="so-prev" style="display:flex;gap:10px;align-items:center"></div></div><div id="so-em" role="status"></div><div class="qa-actions"><button class="qx-btn" type="submit">Save</button><button class="qx-btn ghost" type="button" id="so-x">Cancel</button></div></form>',1);
      var P=$('#so-p'),N=$('#so-n'),U=$('#so-u'),T=$('#so-svg');
      function cur(){var ic=($('input[name=ic]:checked')||{}).value||'link',cu=ic==='__custom';return {platform:P.value,icon_key:cu?null:ic,icon_svg:cu?QX.safe.svg(T.value):null,_bad:cu&&T.value.trim()&&!QX.safe.svg(T.value)};}
      function prev(){var c=cur();$('#so-cu').hidden=($('input[name=ic]:checked')||{}).value!=='__custom';$('#so-prev').innerHTML='<span class="qa2-ic">'+svgIcon(c)+'</span><span>'+E(N.value||'Name')+'</span>'+(c._bad?'<span class="qx-status err">This SVG cannot be used.</span>':'');}
      P.onchange=function(){var k=P.value;if(k!=='custom'){N.value=N.value&&N.dataset.t?N.value:ICONS[k][0];N.dataset.t='';var rad=main.ownerDocument.querySelector('input[name=ic][value="'+k+'"]');if(rad)rad.checked=true;}prev();};
      N.oninput=function(){N.dataset.t='1';prev();};T.oninput=prev;$('#so-ic').onchange=prev;
      $('#so-file').onchange=function(){var f=this.files[0];if(!f)return;if(f.size>20000){msg($('#so-em'),'SVG files must be under 20 KB.',1);return;}var fr=new FileReader();fr.onload=function(){T.value=String(fr.result);prev();};fr.readAsText(f);};
      $('#so-x').onclick=closeModal;prev();
      $('#so-f').onsubmit=async function(ev){ev.preventDefault();var em=$('#so-em'),c=cur(),url=QX.safe.link(U.value);
        if(!N.value.trim()){msg(em,'Please enter a name.',1);return;}if(!url){msg(em,'Enter a valid link starting with https://',1);return;}
        if(c._bad||(!c.icon_key&&!c.icon_svg)){msg(em,'Choose an icon, or paste a valid SVG.',1);return;}
        var pl=[].map.call(document.querySelectorAll('.so-pl:checked'),function(x){return x.value;});
        var row={platform:c.platform,name:N.value.trim(),url:url,icon_key:c.icon_key,icon_svg:c.icon_svg,placements:pl,visible:$('#so-v').checked,sort_order:r.sort_order};if(r.id)row.id=r.id;
        try{await S.save('social_links',row);closeModal();social();toast('Saved. It is live on the website.');}catch(e){msg(em,e.message,1);}};
    }
  }).catch(function(e){main.innerHTML='<h1>Social media</h1><div class="qx-status err">'+E(e.message)+' (Run supabase/migration-v4.sql first.)</div>';});
}

/* ================================ FORM BUILDER ============================== */
var FTYPES=[['text','Short text'],['textarea','Long text'],['email','Email'],['tel','Telephone'],['number','Number'],['select','Dropdown'],['multiselect','Multi-select'],['radio','Radio buttons'],['checkbox','Single checkbox'],['date','Date'],['file','File upload'],['url','Website URL'],['subject','Subject'],['consent','Consent checkbox'],['hidden','Hidden field']];
var emails=function(v){return String(v||'').split(/[\s,;]+/).filter(Boolean);};
var okMail=function(x){return /^[^\s@<>"']+@[^\s@<>"']+\.[^\s@<>"']+$/.test(x);};
function forms(){
  css();main.innerHTML='<h1>Form builder</h1><div class="qa-loading">Loading…</div>';
  Promise.all([S.list('forms',{order:['created_at','asc']}),S.list('form_submissions',{where:{status:'new'}}).catch(function(){return [];})]).then(function(r){
    var rows=r[0],nw={};r[1].forEach(function(s){nw[s.form_id]=(nw[s.form_id]||0)+1;});
    main.innerHTML='<div class="qa-head"><h1>Form builder</h1><button class="qx-btn" id="fm-new">+ New form</button></div><p class="qa-muted" style="max-width:780px;margin:-6px 0 16px">Create forms, choose the fields, set who receives the messages. The <strong>project-enquiry</strong> form is the one on the Contact page. Any form can also be shown on its own page at <code>form.html?f=<em>form-name</em></code>.</p><div id="fm-msg"></div>'+
    '<table class="qa2-list"><thead><tr><th>Form</th><th>Web name</th><th>Sends to</th><th>New messages</th><th>Status</th><th></th></tr></thead><tbody>'+rows.map(function(f,i){return '<tr><td><strong>'+E(f.name)+'</strong></td><td><code>'+E(f.slug)+'</code></td><td>'+E((f.recipients||[]).join(', ')||'⚠ nobody yet (messages are only stored)')+'</td><td>'+(nw[f.id]||0)+'</td><td>'+badge(f.enabled?'published':'draft',[['published','Active'],['draft','Disabled']])+'</td><td><button class="qx-btn ghost qa2-mini" data-e="'+i+'">Edit</button> <button class="qx-btn ghost qa2-mini" data-d="'+i+'">Delete</button></td></tr>';}).join('')+'</tbody></table>';
    $('#fm-new').onclick=function(){openModal('<h2 style="margin-top:0">New form</h2><form id="nf"><div class="qx-field"><label>Form name</label><input id="nf-n" maxlength="80"></div><div class="qx-field"><label>Web name</label><input id="nf-s" maxlength="60" placeholder="partner-enquiry"><small>Lowercase letters, numbers, hyphens.</small></div><div id="nf-m"></div><div class="qa-actions"><button class="qx-btn">Create</button><button type="button" class="qx-btn ghost" id="nf-x">Cancel</button></div></form>');$('#nf-x').onclick=closeModal;$('#nf-n').oninput=function(){if(!$('#nf-s').dataset.t)$('#nf-s').value=QX.util.slugify(this.value);};$('#nf-s').oninput=function(){this.dataset.t=1;};
      $('#nf').onsubmit=async function(ev){ev.preventDefault();var n=$('#nf-n').value.trim(),s=$('#nf-s').value.trim();if(!n||!/^[a-z0-9-]{2,60}$/.test(s)){msg($('#nf-m'),'Enter a name and a web name (lowercase letters, numbers, hyphens).',1);return;}try{var f=await S.save('forms',{name:n,slug:s,title_en:n,recipients:[],enabled:true});await S.save('form_fields',{form_id:f.id,name:'name',type:'text',label_en:'Your name',label_fr:'Votre nom',required:true,sort_order:10});await S.save('form_fields',{form_id:f.id,name:'email',type:'email',label_en:'Email',label_fr:'E-mail',required:true,sort_order:20});await S.save('form_fields',{form_id:f.id,name:'message',type:'textarea',label_en:'Message',label_fr:'Message',required:true,wide:true,sort_order:30});closeModal();editForm(f.id);}catch(e){msg($('#nf-m'),e.message,1);}};};
    main.querySelectorAll('[data-e]').forEach(function(b){b.onclick=function(){editForm(rows[+b.dataset.e].id);};});
    main.querySelectorAll('[data-d]').forEach(function(b){b.onclick=function(){var f=rows[+b.dataset.d];if(f.slug==='project-enquiry'){toast('The Contact page form cannot be deleted. Disable it instead.',true);return;}confirmBox('Delete the form “'+f.name+'” and its fields? Messages already received are kept.','Delete form',async function(){try{await S.remove('forms',f.id);forms();}catch(e){toast(e.message,true);}});};});
  }).catch(function(e){main.innerHTML='<h1>Form builder</h1><div class="qx-status err">'+E(e.message)+' (Run supabase/migration-v4.sql first.)</div>';});
}
function editForm(id){
  var tab='settings';
  Promise.all([S.get('forms',id),S.list('form_fields',{where:{form_id:id},order:['sort_order','asc']})]).then(function(r){
    var f=r[0],fields=r[1];if(!f){forms();return;}
    function draw(){
      main.innerHTML='<div class="qa-head"><h1>'+E(f.name)+'</h1><button class="qx-btn ghost" id="fe-back">← All forms</button></div><div class="qa2-tabs"><button data-t="settings" aria-selected="'+(tab==='settings')+'">Settings & email</button><button data-t="fields" aria-selected="'+(tab==='fields')+'">Fields ('+fields.length+')</button></div><div id="fe-msg" role="status"></div><div id="fe-body"></div>';
      $('#fe-back').onclick=forms;main.querySelectorAll('[data-t]').forEach(function(b){b.onclick=function(){tab=b.dataset.t;draw();};});
      tab==='settings'?settings():fieldList();
    }
    function settings(){
      var t=function(id,l,v,h,type){return field(l,'<input type="'+(type||'text')+'" id="'+id+'" value="'+E(v==null?'':v)+'">',h);};
      var a=function(id,l,v,rows,h){return field(l,'<textarea id="'+id+'" rows="'+(rows||3)+'">'+E(v==null?'':v)+'</textarea>',h);};
      $('#fe-body').innerHTML='<form id="fs" class="qa-panel" novalidate style="max-width:860px"><h3 style="margin-top:0">Wording</h3>'+field('Form name (internal)','<input id="fs-name" value="'+E(f.name)+'">')+'<div class="qa2-grid2">'+t('fs-te','Title (English)',f.title_en)+t('fs-tf','Title (Français)',f.title_fr)+a('fs-de','Description (English)',f.description_en)+a('fs-df','Description (Français)',f.description_fr)+t('fs-se','Submit button (English)',f.submit_en)+t('fs-sf','Submit button (Français)',f.submit_fr)+t('fs-ue','Success message (English)',f.success_en)+t('fs-uf','Success message (Français)',f.success_fr)+t('fs-ee','Error message (English)',f.error_en)+t('fs-ef','Error message (Français)',f.error_fr)+a('fs-ne','Note under the button (English)',f.note_en)+a('fs-nf','Note under the button (Français)',f.note_fr)+'</div>'+t('fs-red','Redirect page after sending (optional)',f.redirect_url,'Example: thank-you.html. If empty, the success message is shown instead.')+
      '<h3>Email delivery</h3>'+a('fs-rec','Send new messages to',(f.recipients||[]).join('\n'),3,'One address per line. You can change this at any time. Staff addresses are never shown to visitors.')+'<div class="qa2-grid2">'+a('fs-cc','CC',(f.cc||[]).join('\n'),2)+a('fs-bcc','BCC',(f.bcc||[]).join('\n'),2)+'</div><label style="display:block;margin:8px 0"><input type="checkbox" id="fs-ack"'+(f.ack_enabled?' checked':'')+'> Send an automatic acknowledgement to the visitor (needs an Email field in the form)</label><div class="qa2-grid2">'+t('fs-ase','Acknowledgement subject (English)',f.ack_subject_en)+t('fs-asf','Acknowledgement subject (Français)',f.ack_subject_fr)+a('fs-abe','Acknowledgement message (English)',f.ack_body_en,4)+a('fs-abf','Acknowledgement message (Français)',f.ack_body_fr,4)+'</div><label style="display:block;margin:8px 0"><input type="checkbox" id="fs-en"'+(f.enabled?' checked':'')+'> Form is active (untick to switch it off; the Contact page then shows its original form)</label><div class="qa-actions"><button class="qx-btn" type="submit">Save form settings</button></div></form>';
      $('#fs').onsubmit=async function(ev){ev.preventDefault();var g=function(i){return $('#'+i).value.trim();},em=$('#fe-msg'),rc=emails(g('fs-rec')),cc=emails(g('fs-cc')),bc=emails(g('fs-bcc'));
        var bad=rc.concat(cc,bc).filter(function(x){return !okMail(x);});if(bad.length){msg(em,'Not a valid email address: '+bad[0],1);return;}
        var red=g('fs-red');if(red&&!/^(https:\/\/|\/|[a-z0-9._-]+\.html)/i.test(red)){msg(em,'The redirect must be a page like thank-you.html or a https:// link.',1);return;}
        if(!g('fs-name')){msg(em,'The form needs a name.',1);return;}
        var row={id:f.id,name:g('fs-name'),title_en:g('fs-te'),title_fr:g('fs-tf'),description_en:g('fs-de'),description_fr:g('fs-df'),submit_en:g('fs-se'),submit_fr:g('fs-sf'),success_en:g('fs-ue'),success_fr:g('fs-uf'),error_en:g('fs-ee'),error_fr:g('fs-ef'),note_en:g('fs-ne'),note_fr:g('fs-nf'),redirect_url:red||null,recipients:rc,cc:cc,bcc:bc,ack_enabled:$('#fs-ack').checked,ack_subject_en:g('fs-ase'),ack_subject_fr:g('fs-asf'),ack_body_en:g('fs-abe'),ack_body_fr:g('fs-abf'),enabled:$('#fs-en').checked};
        try{f=await S.save('forms',row)||Object.assign(f,row);msg(em,'Saved. The change is live.');}catch(e){msg(em,e.message,1);}};
    }
    function fieldList(){
      $('#fe-body').innerHTML='<div style="margin-bottom:12px"><button class="qx-btn" id="ff-add">+ Add field</button></div>'+(fields.length?'<table class="qa2-list"><thead><tr><th>Label</th><th>Type</th><th>Required</th><th>Visible</th><th></th></tr></thead><tbody>'+fields.map(function(x,i){return '<tr><td><strong>'+E(x.label_en)+'</strong><br><small class="qa-muted">'+E(x.name)+'</small></td><td>'+E((FTYPES.filter(function(t){return t[0]===x.type;})[0]||[0,x.type])[1])+'</td><td>'+(x.required?'Yes':'No')+'</td><td>'+(x.visible?'Yes':'Hidden')+'</td><td style="white-space:nowrap"><button class="qx-btn ghost qa2-mini" data-u="'+i+'" '+(i?'':'disabled')+' aria-label="Move up">↑</button> <button class="qx-btn ghost qa2-mini" data-n="'+i+'" '+(i<fields.length-1?'':'disabled')+' aria-label="Move down">↓</button> <button class="qx-btn ghost qa2-mini" data-e="'+i+'">Edit</button> <button class="qx-btn ghost qa2-mini" data-x="'+i+'">Delete</button></td></tr>';}).join('')+'</tbody></table>':'<div class="qa-empty">No fields yet.</div>');
      $('#ff-add').onclick=function(){fieldEdit(null);};
      var by=function(a,fn){main.querySelectorAll('['+a+']').forEach(function(b){b.onclick=function(){fn(+b.getAttribute(a));};});};
      by('data-e',function(i){fieldEdit(fields[i]);});
      by('data-u',function(i){mv(i,i-1);});by('data-n',function(i){mv(i,i+1);});
      by('data-x',function(i){confirmBox('Delete the field “'+fields[i].label_en+'”? Past messages keep their data.','Delete field',async function(){try{await S.remove('form_fields',fields[i].id);fields.splice(i,1);draw();}catch(e){toast(e.message,true);}});});
      async function mv(a,b){try{var x=fields[a];fields[a]=fields[b];fields[b]=x;for(var k=0;k<fields.length;k++){if(fields[k].sort_order!==(k+1)*10){fields[k].sort_order=(k+1)*10;await S.save('form_fields',{id:fields[k].id,sort_order:(k+1)*10});}}draw();}catch(e){toast(e.message,true);}}
    }
    function fieldEdit(x){
      var isNew=!x;x=x||{name:'',type:'text',label_en:'',label_fr:'',placeholder_en:'',placeholder_fr:'',help_en:'',help_fr:'',options:[],required:false,validation:{},default_value:'',visible:true,wide:false,sort_order:(fields.length+1)*10};
      var v=x.validation||{},opts=(x.options||[]).map(function(o){return o.en+(o.fr&&o.fr!==o.en?' | '+o.fr:'');}).join('\n');
      var i=function(id,l,val,h,type){return field(l,'<input type="'+(type||'text')+'" id="'+id+'" value="'+E(val==null?'':val)+'">',h);};
      openModal('<h2 style="margin-top:0">'+(isNew?'Add':'Edit')+' field</h2><form id="ffm" novalidate>'+field('Field type','<select id="ff-t">'+FTYPES.map(function(t){return '<option value="'+t[0]+'"'+(x.type===t[0]?' selected':'')+'>'+E(t[1])+'</option>';}).join('')+'</select>')+'<div class="qa2-grid2">'+i('ff-le','Label (English)',x.label_en,'',0)+i('ff-lf','Label (Français)',x.label_fr)+i('ff-pe','Placeholder (English)',x.placeholder_en)+i('ff-pf','Placeholder (Français)',x.placeholder_fr)+i('ff-he','Help text (English)',x.help_en)+i('ff-hf','Help text (Français)',x.help_fr)+'</div>'+
        i('ff-n','Field code',x.name,isNew?'Letters, numbers, underscore; starts with a letter. Cannot be changed later.':'Cannot be changed.')+
        '<div id="ff-ow">'+field('Choices','<textarea id="ff-o" rows="5" placeholder="English | Français (one per line)">'+E(opts)+'</textarea>','One choice per line. Write the English text, then | and the French text.')+'</div>'+
        '<div class="qa2-grid2">'+i('ff-d','Default value',x.default_value)+i('ff-ml','Maximum length (characters)',v.maxlength,'','number')+i('ff-nl','Minimum length',v.minlength,'','number')+i('ff-mn','Minimum value (numbers)',v.min,'','number')+i('ff-mx','Maximum value (numbers)',v.max,'','number')+i('ff-pt','Pattern (advanced, regular expression)',v.pattern)+'</div>'+
        '<label style="display:block"><input type="checkbox" id="ff-r"'+(x.required?' checked':'')+'> Required</label><label style="display:block"><input type="checkbox" id="ff-w"'+(x.wide?' checked':'')+'> Full width</label><label style="display:block"><input type="checkbox" id="ff-v"'+(x.visible?' checked':'')+'> Visible</label><div id="ff-em" role="status"></div><div class="qa-actions"><button class="qx-btn" type="submit">Save field</button><button class="qx-btn ghost" type="button" id="ff-x">Cancel</button></div></form>',1);
      var T=$('#ff-t'),sync=function(){$('#ff-ow').hidden=['select','multiselect','radio'].indexOf(T.value)<0;};T.onchange=sync;sync();$('#ff-x').onclick=closeModal;if(!isNew)$('#ff-n').readOnly=true;
      $('#ff-le').oninput=function(){if(isNew&&!$('#ff-n').dataset.t)$('#ff-n').value=QX.util.slugify(this.value).replace(/-/g,'_').replace(/^[^a-z]+/,'').slice(0,40);};$('#ff-n').oninput=function(){this.dataset.t=1;};
      $('#ffm').onsubmit=async function(ev){ev.preventDefault();var g=function(q){return $('#'+q).value.trim();},em=$('#ff-em'),type=T.value;
        if(!g('ff-le')){msg(em,'Enter the English label.',1);return;}if(!/^[a-z][a-z0-9_]{0,39}$/.test(g('ff-n'))){msg(em,'The field code must start with a letter and use only a-z, 0-9 and _ (max 40).',1);return;}
        if(isNew&&fields.some(function(q){return q.name===g('ff-n');})){msg(em,'Another field already uses that code.',1);return;}
        var options=[];if(['select','multiselect','radio'].indexOf(type)>-1){options=g('ff-o').split('\n').map(function(l){return l.trim();}).filter(Boolean).map(function(l){var p=l.split('|').map(function(z){return z.trim();});return {value:p[0],en:p[0],fr:p[1]||p[0]};});if(!options.length){msg(em,'Add at least one choice.',1);return;}}
        var val={};if(g('ff-ml'))val.maxlength=+g('ff-ml');if(g('ff-nl'))val.minlength=+g('ff-nl');if(g('ff-mn'))val.min=+g('ff-mn');if(g('ff-mx'))val.max=+g('ff-mx');
        if(g('ff-pt')){if(g('ff-pt').length>200){msg(em,'The pattern is too long.',1);return;}try{new RegExp(g('ff-pt'));}catch(e){msg(em,'The pattern is not a valid regular expression.',1);return;}val.pattern=g('ff-pt');}
        var row={form_id:f.id,name:g('ff-n'),type:type,label_en:g('ff-le'),label_fr:g('ff-lf')||null,placeholder_en:g('ff-pe')||null,placeholder_fr:g('ff-pf')||null,help_en:g('ff-he')||null,help_fr:g('ff-hf')||null,options:options,validation:val,default_value:g('ff-d')||null,required:$('#ff-r').checked,wide:$('#ff-w').checked,visible:$('#ff-v').checked,sort_order:x.sort_order};if(x.id)row.id=x.id;
        try{var saved=await S.save('form_fields',row);if(x.id){Object.assign(x,row);}else fields.push(saved||row);closeModal();var ff=await S.list('form_fields',{where:{form_id:f.id},order:['sort_order','asc']});fields=ff;draw();}catch(e){msg(em,e.message,1);}};
    }
    draw();
  });
}

/* =============================== SUBMISSIONS =============================== */
var SSTAT=[['new','New'],['read','Read'],['in_progress','In progress'],['resolved','Resolved']];
function submissions(){
  css();main.innerHTML='<h1>Form submissions</h1><div class="qa-loading">Loading…</div>';
  Promise.all([S.list('form_submissions',{order:['created_at','desc'],limit:1000}),S.list('forms')]).then(function(r){
    var rows=r[0],fm={};r[1].forEach(function(f){fm[f.id]=f;});
    var st={q:'',form:'',status:'',arch:'0'};
    function vis(){var q=st.q.toLowerCase();return rows.filter(function(x){return (!st.form||x.form_id===st.form)&&(!st.status||x.status===st.status)&&(st.arch==='all'||String(+!!x.archived)===st.arch)&&(!q||JSON.stringify(x.data).toLowerCase().indexOf(q)>-1||String(x.form_name).toLowerCase().indexOf(q)>-1);});}
    function show(){var v=vis();
      $('#sb-list').innerHTML=v.length?'<table class="qa2-list"><thead><tr><th>Received</th><th>Form</th><th>From</th><th>Summary</th><th>Status</th></tr></thead><tbody>'+v.map(function(x,i){var d=x.data||{};return '<tr data-i="'+i+'" style="cursor:pointer"><td>'+E(dt(x.created_at))+'</td><td>'+E(x.form_name||'')+'</td><td>'+E(d.name||d.email||'')+'</td><td style="max-width:320px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+E(d.message||d.service||'')+'</td><td>'+badge(x.status,SSTAT)+(x.archived?' <span class="qx-badge">archived</span>':'')+'</td></tr>';}).join('')+'</tbody></table>':'<div class="qa-empty">No submissions match.</div>';
      $('#sb-list').querySelectorAll('tr[data-i]').forEach(function(tr){tr.onclick=function(){open(v[+tr.dataset.i]);};});
      $('#sb-csv').disabled=!v.length;$('#sb-csv').onclick=function(){var keys=[];v.forEach(function(x){Object.keys(x.data||{}).forEach(function(k){if(keys.indexOf(k)<0)keys.push(k);});});download('form-submissions-'+new Date().toISOString().slice(0,10)+'.csv',[['Received','Form','Status','Archived','Notes'].concat(keys)].concat(v.map(function(x){return [x.created_at,x.form_name,x.status,x.archived,x.notes].concat(keys.map(function(k){return (x.data||{})[k];}));})));};}
    main.innerHTML='<div class="qa-head"><h1>Form submissions</h1><button class="qx-btn ghost" id="sb-csv">Export CSV</button></div><div class="qx-toolbar" style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px"><input id="sb-q" placeholder="Search…" aria-label="Search"><select id="sb-f" aria-label="Form"><option value="">All forms</option>'+r[1].map(function(f){return '<option value="'+f.id+'">'+E(f.name)+'</option>';}).join('')+'</select><select id="sb-s" aria-label="Status"><option value="">Any status</option>'+SSTAT.map(function(s){return '<option value="'+s[0]+'">'+s[1]+'</option>';}).join('')+'</select><select id="sb-a" aria-label="Archive"><option value="0">Active</option><option value="1">Archived</option><option value="all">All</option></select></div><div id="sb-list"></div>';
    [['sb-q','q','input'],['sb-f','form','change'],['sb-s','status','change'],['sb-a','arch','change']].forEach(function(p){$('#'+p[0]).addEventListener(p[2],function(){st[p[1]]=this.value;show();});});show();
    function open(x){
      var d=x.data||{},f=fm[x.form_id],lab={};if(f){}
      S.list('form_fields',{where:{form_id:x.form_id}}).catch(function(){return [];}).then(function(fl){fl.forEach(function(q){lab[q.name]=q;});
        var body=Object.keys(d).map(function(k){var q=lab[k],val=d[k],shown=Array.isArray(val)?val.join(', '):String(val);return '<div class="qx-field"><label>'+E(q?q.label_en:k)+'</label>'+(q&&q.type==='file'?'<button type="button" class="qx-btn ghost qa2-mini" data-file="'+E(val)+'">Open attachment</button>':'<div style="white-space:pre-wrap;word-break:break-word">'+E(shown)+'</div>')+'</div>';}).join('');
        openModal('<h2 style="margin-top:0">'+E(x.form_name||'Submission')+'</h2><p class="qa-muted">Received '+E(dt(x.created_at))+' · language '+E((x.lang||'en').toUpperCase())+'</p>'+body+'<hr>'+field('Status','<select id="sm-s">'+SSTAT.map(function(s){return '<option value="'+s[0]+'"'+(x.status===s[0]?' selected':'')+'>'+s[1]+'</option>';}).join('')+'</select>')+field('Private staff notes','<textarea id="sm-n" rows="4">'+E(x.notes||'')+'</textarea>','Never shown to the visitor.')+'<div id="sm-m"></div><div class="qa-actions"><button class="qx-btn" id="sm-save">Save</button><button class="qx-btn ghost" id="sm-arch">'+(x.archived?'Unarchive':'Archive')+'</button><button class="qx-btn ghost" id="sm-del" style="color:#b00000">Delete</button><button class="qx-btn ghost" id="sm-x">Close</button></div>',1);
        $('#sm-x').onclick=closeModal;
        modalFiles();
        $('#sm-save').onclick=async function(){try{await S.save('form_submissions',{id:x.id,status:$('#sm-s').value,notes:$('#sm-n').value.trim()||null});x.status=$('#sm-s').value;x.notes=$('#sm-n').value.trim()||null;closeModal();show();toast('Saved.');}catch(e){msg($('#sm-m'),e.message,1);}};
        $('#sm-arch').onclick=async function(){try{await S.save('form_submissions',{id:x.id,archived:!x.archived});x.archived=!x.archived;closeModal();show();}catch(e){msg($('#sm-m'),e.message,1);}};
        $('#sm-del').onclick=function(){confirmBox('Permanently delete this submission? This cannot be undone.','Delete',async function(){try{await S.remove('form_submissions',x.id);rows.splice(rows.indexOf(x),1);show();toast('Deleted.');}catch(e){toast(e.message,true);}});};
        if(x.status==='new'){S.save('form_submissions',{id:x.id,status:'read'}).then(function(){x.status='read';show();}).catch(function(){});}
      });
    }
    function modalFiles(){document.querySelectorAll('[data-file]').forEach(function(b){b.onclick=async function(){try{var u=await S.signedUrl('uploads',b.dataset.file);if(u)window.open(u,'_blank','noopener');}catch(e){toast('Could not open the file.',true);}};});}
  }).catch(function(e){main.innerHTML='<h1>Form submissions</h1><div class="qx-status err">'+E(e.message)+'</div>';});
}

/* ============================== STAFF & ROLES ============================== */
function staff(){
  css();main.innerHTML='<h1>Staff & roles</h1><div class="qa-loading">Loading…</div>';
  S.list('staff',{order:['created_at','asc']}).then(function(rows){
    var me=QX.auth.session().user.id;
    main.innerHTML='<div class="qa-head"><h1>Staff & roles</h1><button class="qx-btn" id="st-inv">+ Invite staff member</button></div><div id="st-msg"></div><table class="qa2-list"><thead><tr><th>Person</th><th>Role</th><th>Status</th><th></th></tr></thead><tbody>'+rows.map(function(s,i){return '<tr><td><strong>'+E(s.display_name||s.email)+'</strong><br><small class="qa-muted">'+E(s.email)+'</small></td><td><select data-r="'+i+'" aria-label="Role for '+E(s.email)+'">'+ROLES.map(function(r){return '<option value="'+r[0]+'"'+(s.role===r[0]?' selected':'')+'>'+E(r[1])+'</option>';}).join('')+'</select></td><td>'+badge(s.active?'published':'draft',[['published','Active'],['draft','Deactivated']])+'</td><td style="white-space:nowrap"><button class="qx-btn ghost qa2-mini" data-a="'+i+'">'+(s.active?'Deactivate':'Reactivate')+'</button> <button class="qx-btn ghost qa2-mini" data-x="'+i+'" '+(s.user_id===me?'disabled':'')+'>Remove</button></td></tr>';}).join('')+'</tbody></table><h3 style="margin-top:26px">What each role can do</h3><table class="qa2-list"><tbody>'+ROLES.map(function(r){return '<tr><td><strong>'+E(r[1])+'</strong></td><td>'+E(r[2])+'</td></tr>';}).join('')+'</tbody></table>';
    main.querySelectorAll('[data-r]').forEach(function(sel){sel.onchange=async function(){var s=rows[+sel.dataset.r];try{await QX_patch(s.user_id,{role:sel.value});toast('Role updated.');staff();}catch(e){toast(e.message,true);staff();}};});
    main.querySelectorAll('[data-a]').forEach(function(b){b.onclick=async function(){var s=rows[+b.dataset.a];try{await QX_patch(s.user_id,{active:!s.active});toast(s.active?'Access removed.':'Access restored.');staff();}catch(e){toast(e.message,true);}};});
    main.querySelectorAll('[data-x]').forEach(function(b){b.onclick=function(){var s=rows[+b.dataset.x];confirmBox('Remove '+s.email+' from the staff list? They will no longer be able to open this portal.','Remove',async function(){try{await QX_del(s.user_id);staff();}catch(e){toast(e.message,true);}});};});
    $('#st-inv').onclick=function(){
      openModal('<h2 style="margin-top:0">Invite a staff member</h2><form id="iv" novalidate>'+field('Email','<input type="email" id="iv-e">','',1)+field('Name (optional)','<input id="iv-n" maxlength="80">')+field('Role','<select id="iv-r">'+ROLES.map(function(r){return '<option value="'+r[0]+'"'+(r[0]==='content'?' selected':'')+'>'+E(r[1])+' — '+E(r[2])+'</option>';}).join('')+'</select>')+'<p class="qa-muted">They receive an email to set their own password. You never see or choose it.</p><div id="iv-m" role="status"></div><div class="qa-actions"><button class="qx-btn">Send invitation</button><button type="button" class="qx-btn ghost" id="iv-x">Cancel</button></div></form>');
      $('#iv-x').onclick=closeModal;
      $('#iv').onsubmit=async function(ev){ev.preventDefault();var e=$('#iv-e').value.trim();if(!okMail(e)){msg($('#iv-m'),'Enter a valid email address.',1);return;}
        try{var s=QX.auth.session(),res=await fetch(QX.config.supabaseUrl+'/functions/v1/staff-admin',{method:'POST',headers:{'Content-Type':'application/json',apikey:QX.config.supabaseAnonKey,Authorization:'Bearer '+s.access_token},body:JSON.stringify({action:'invite',email:e,name:$('#iv-n').value.trim(),role:$('#iv-r').value,redirectTo:location.origin+location.pathname.replace(/[^/]*$/,'')+'portal.html'})});
          var j=await res.json().catch(function(){return {};});if(!res.ok)throw new Error(j.error||('The invitation service answered '+res.status+'. Is the staff-admin function deployed?'));closeModal();toast('Invitation sent to '+e);staff();}catch(x){msg($('#iv-m'),x.message,1);}};};
  }).catch(function(e){main.innerHTML='<h1>Staff & roles</h1><div class="qx-status err">'+E(e.message)+'</div>';});
}
async function QX_patch(uid,patch){var r=await fetch(QX.config.supabaseUrl+'/rest/v1/staff?user_id=eq.'+encodeURIComponent(uid),{method:'PATCH',headers:{apikey:QX.config.supabaseAnonKey,Authorization:'Bearer '+QX.auth.session().access_token,'Content-Type':'application/json',Prefer:'return=representation'},body:JSON.stringify(Object.assign({},patch,{updated_at:new Date().toISOString()}))});var j=await r.json().catch(function(){return null;});if(!r.ok)throw new Error((j&&j.message)||'Not allowed');if(!j||!j.length)throw new Error('Not allowed');return j[0];}
async function QX_del(uid){var r=await fetch(QX.config.supabaseUrl+'/rest/v1/staff?user_id=eq.'+encodeURIComponent(uid),{method:'DELETE',headers:{apikey:QX.config.supabaseAnonKey,Authorization:'Bearer '+QX.auth.session().access_token,Prefer:'return=representation'}});var j=await r.json().catch(function(){return null;});if(!r.ok)throw new Error((j&&j.message)||'Not allowed');}

/* =============================== ACTIVITY LOG ============================== */
var RESTORABLE={solutions:'id',posts:'id',jobs:'id',tenders:'id',partners:'id',social_links:'id',forms:'id',form_fields:'id',site_settings:'key'};
function activity(){
  css();main.innerHTML='<h1>Activity log</h1><div class="qa-loading">Loading…</div>';
  S.list('activity_log',{order:['at','desc'],limit:400}).then(function(rows){
    var tables=[];rows.forEach(function(r){if(tables.indexOf(r.table_name)<0)tables.push(r.table_name);});var f='';
    function show(){var v=rows.filter(function(r){return !f||r.table_name===f;});
      $('#al-l').innerHTML=v.length?'<table class="qa2-list"><thead><tr><th>When</th><th>Who</th><th>What</th><th>Item</th><th></th></tr></thead><tbody>'+v.map(function(r,i){return '<tr><td>'+E(dt(r.at))+'</td><td>'+E(r.actor_email||'—')+'</td><td>'+E({INSERT:'Created',UPDATE:'Changed',DELETE:'Deleted'}[r.op]||r.op)+' · '+E(r.table_name)+'</td><td style="max-width:260px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+E(label(r))+'</td><td><button class="qx-btn ghost qa2-mini" data-i="'+i+'">Details</button></td></tr>';}).join('')+'</tbody></table>':'<div class="qa-empty">Nothing recorded yet.</div>';
      $('#al-l').querySelectorAll('[data-i]').forEach(function(b){b.onclick=function(){detail(v[+b.dataset.i]);};});}
    function label(r){var v=r.new_value||r.old_value||{};return v.title_en||v.name||v.label_en||v.key||v.slug||v.email||v.reference||r.row_id||'';}
    main.innerHTML='<div class="qa-head"><h1>Activity log</h1><button class="qx-btn ghost" id="al-csv">Export CSV</button></div><p class="qa-muted" style="max-width:760px;margin:-6px 0 14px">Every change made in this portal is recorded: who, when, and the earlier and new values. Applications and form messages are recorded by status only; their personal details are never copied here.</p><select id="al-f" aria-label="Filter"><option value="">All areas</option>'+tables.map(function(t){return '<option>'+E(t)+'</option>';}).join('')+'</select><div id="al-l" style="margin-top:12px"></div>';
    $('#al-f').onchange=function(){f=this.value;show();};show();
    $('#al-csv').onclick=function(){download('activity-log.csv',[['When','Who','Operation','Area','Item','Old value','New value']].concat(rows.map(function(r){return [r.at,r.actor_email,r.op,r.table_name,label(r),r.old_value,r.new_value];})));};
    function detail(r){
      var can=RESTORABLE[r.table_name]&&r.old_value&&(r.op==='UPDATE'||r.op==='DELETE');
      var diff=r.op==='UPDATE'?Object.keys(r.new_value||{}).filter(function(k){return JSON.stringify(r.new_value[k])!==JSON.stringify((r.old_value||{})[k])&&k!=='updated_at';}):Object.keys(r.new_value||r.old_value||{});
      openModal('<h2 style="margin-top:0">'+E(label(r)||r.table_name)+'</h2><p class="qa-muted">'+E(dt(r.at))+' · '+E(r.actor_email||'')+' · '+E(r.op)+'</p>'+diff.slice(0,40).map(function(k){var o=(r.old_value||{})[k],n=(r.new_value||{})[k],sh=function(v){var t=v==null?'—':(typeof v==='object'?JSON.stringify(v):String(v));return E(t.length>400?t.slice(0,400)+'…':t);};return '<div class="qx-field"><label>'+E(k)+'</label>'+(r.op==='UPDATE'?'<div class="qa2-pre">Before: '+sh(o)+'\nAfter:  '+sh(n)+'</div>':'<div class="qa2-pre">'+sh(n==null?o:n)+'</div>')+'</div>';}).join('')+'<div id="al-m"></div><div class="qa-actions">'+(can?'<button class="qx-btn" id="al-rs">Restore the earlier version</button>':'')+'<button class="qx-btn ghost" id="al-x">Close</button></div>',1);
      $('#al-x').onclick=closeModal;
      if(can)$('#al-rs').onclick=function(){confirmBox('Put this item back to how it was before this change? The restore itself is also logged.','Restore',async function(){try{var row=Object.assign({},r.old_value);delete row.updated_at;var key=RESTORABLE[r.table_name];if(key==='key')await S.upsert(r.table_name,row,'key');else{var ex=await S.list(r.table_name,{where:{id:row.id}});if(ex.length){var id=row.id;await S.save(r.table_name,Object.assign({},row,{id:id}));}else{await QX_insert(r.table_name,row);}}toast('Restored.');activity();}catch(e){toast(e.message,true);}});};
    }
  }).catch(function(e){main.innerHTML='<h1>Activity log</h1><div class="qx-status err">'+E(e.message)+'</div>';});
}
async function QX_insert(table,row){var r=await fetch(QX.config.supabaseUrl+'/rest/v1/'+table,{method:'POST',headers:{apikey:QX.config.supabaseAnonKey,Authorization:'Bearer '+QX.auth.session().access_token,'Content-Type':'application/json'},body:JSON.stringify(row)});if(!r.ok){var j=await r.json().catch(function(){return {};});throw new Error(j.message||'Could not restore');}}

A.VIEWS.appearance=appearance;A.VIEWS.social=social;A.VIEWS.forms=forms;A.VIEWS.submissions=submissions;A.VIEWS.staff=staff;A.VIEWS.activity=activity;
};
